INSERT INTO MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) VALUES (60022,7,'Cannot enable live casino because this account does not have live casino setting.', N'此帳號沒有娛樂廳設定因此無法啟用', N'此帐号没有娱乐厅设定因此无法启用', N'Cannot enable live casino because this account does not have live casino setting.', N'ไม่สามารถเปิดใช้งานคาสิโนเกมสดได้ เนื่องจากบัญชีนี้ไม่ได้มีการ ตั้งค่าคาสิโนเกมสด', N'이 계정은 라이브 카지노 설정이 없기 때문에 라이브 카지노를 활성화할 수 없습니다.', N'Cannot enable live casino because this account does not have live casino setting.', N'Cannot enable live casino because this account does not have live casino setting.',1)
INSERT INTO MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) VALUES (60023,7,'Cannot enable live casino because this account''s upline is disabled or does not have live casino setting.', N'此帳號的上線以被禁止或沒有娛樂廳設定，所以無法啟用娛樂廳', N'此帐号的上线以被禁止或没有娱乐厅设定，所以无法启用娱乐厅', N'Cannot enable live casino because this account''s upline is disabled or does not have live casino setting.', N'ไม่สามารถเปิด ใช้งานคาสิโนเกมสด เนื่องจาก อัพไลด์  ของบัญชีนี้ปิดการใช้งาน หรือไม่ได้มีการตั้งค่าคาสิโนเกมสด', N'이 계정은 라이브 카지노 설정이 없기 때문에 라이브 카지노를 활성화할 수 없습니다.', N'Cannot enable live casino because this account''s upline is disabled or does not have live casino setting.', N'Cannot enable live casino because this account''s upline is disabled or does not have live casino setting.',1)
INSERT INTO MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) VALUES (60024,7,'Cannot enable Bingo because this account does not have Bingo setting.', N'無法啟用賓果因為此賬戶沒有賓果設置.', N'无法启用宾果因为此账户没有宾果设置.', N'Cannot enable Bingo because this account does not have Bingo setting.', N'ไม่สามารถเปิดการใช้งานบิงโกได้เนื่องจากลูกค้าไม่มีการตั้งค่าของบิงโก.', N'Cannot enable Bingo because this account does not have Bingo setting.', N'Cannot enable Bingo because this account does not have Bingo setting.', N'Cannot enable Bingo because this account does not have Bingo setting.',1)
INSERT INTO MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) VALUES (60025,7,'Cannot enable Bingo because this account''s upline is disabled or does not have Bingo setting.', N'無法啟用賓果因為此賬戶的上線是禁用或沒有賓果設定。', N'无法启用宾果因为此账户的上线是禁用或没有宾果设定。', N'Cannot enable Bingo because this account''s upline is disabled or does not have Bingo setting.', N'ไม่สามารถเปิดการใช้งานบิงโกได้เนื่องจากอัพไลน์ของลูกค้านี้ได้ปิดการใช้งงานหรือไม่ได้ตั้งค่าบิงโก.', N'Cannot enable Bingo because this account''s upline is disabled or does not have Bingo setting.', N'Cannot enable Bingo because this account''s upline is disabled or does not have Bingo setting.', N'Cannot enable Bingo because this account''s upline is disabled or does not have Bingo setting.',1)
